// ─── UNIVERSAL RAW RESPONSE PARSER ────────────────────────────────────
// Normalises HTTP responses from all 10 platforms into a consistent shape.

const keyword  = $('Loop Over Keywords').item.json;
const platform = keyword.Platform || 'Unknown';
const raw      = $json;

let products = [];

try {
  // ── TALABAT ────────────────────────────────────────────────────────────
  if (platform === 'Talabat') {
    const items = raw?.data?.products || raw?.products || raw?.items || [];
    products = items.map(p => ({
      raw_name        : p.name || p.title || '',
      price_egp       : parseFloat(p.price || p.currentPrice || 0),
      original_price  : parseFloat(p.oldPrice || p.originalPrice || 0) || null,
      in_stock        : p.available !== false && p.inStock !== false,
      stock_hint      : p.stockHint || null,
      platform_item_id: String(p.id || ''),
      image_url       : p.image || null
    }));

  // ── BREADFAST ──────────────────────────────────────────────────────────
  } else if (platform === 'Breadfast') {
    const items = raw?.data || raw?.products || raw?.results || [];
    products = items.map(p => ({
      raw_name        : p.name || p.title || '',
      price_egp       : parseFloat(p.price || p.sellingPrice || 0),
      original_price  : parseFloat(p.originalPrice || p.strikePrice || 0) || null,
      in_stock        : p.stock > 0 || p.available === true,
      stock_hint      : p.stockMessage || null,
      platform_item_id: String(p.id || p.sku || ''),
      image_url       : p.image || null
    }));

  // ── RABBIT ─────────────────────────────────────────────────────────────
  } else if (platform === 'Rabbit') {
    const items = raw?.data || raw?.products || raw?.results || [];
    products = items.map(p => ({
      raw_name        : p.name || p.title || p.product_name || '',
      price_egp       : parseFloat(p.price || p.selling_price || 0),
      original_price  : parseFloat(p.original_price || p.crossed_price || 0) || null,
      in_stock        : p.in_stock !== false && p.available !== false,
      stock_hint      : p.stock_status || null,
      platform_item_id: String(p.id || p.product_id || ''),
      image_url       : p.image || p.thumbnail || null
    }));

  // ── NOON ───────────────────────────────────────────────────────────────
  } else if (platform === 'Noon') {
    const items = raw?.data?.products || raw?.hits || raw?.results || [];
    products = items.map(p => ({
      raw_name        : p.name || p.title || '',
      price_egp       : parseFloat(p.price?.value || p.salePrice || p.price || 0),
      original_price  : parseFloat(p.price?.was || p.originalPrice || 0) || null,
      in_stock        : p.inStock !== false && p.qty > 0,
      stock_hint      : null,
      platform_item_id: String(p.sku || p.id || ''),
      image_url       : p.image?.default || p.image || null
    }));

  // ── JUMIA ──────────────────────────────────────────────────────────────
  } else if (platform === 'Jumia') {
    // Jumia returns HTML — parse basic fields
    const html = typeof raw === 'string' ? raw : JSON.stringify(raw);
    const nameMatches  = [...html.matchAll(/data-name="([^"]+)"/g)];
    const priceMatches = [...html.matchAll(/data-price="([\d.]+)"/g)];
    products = nameMatches.slice(0, 20).map((m, i) => ({
      raw_name        : m[1],
      price_egp       : parseFloat(priceMatches[i]?.[1] || 0),
      original_price  : null,
      in_stock        : true,
      stock_hint      : null,
      platform_item_id: `jumia-${i}`,
      image_url       : null
    }));

  // ── CARREFOUR ──────────────────────────────────────────────────────────
  } else if (platform === 'Carrefour') {
    const html = typeof raw === 'string' ? raw : JSON.stringify(raw);
    // Adapt after Playwright/ScraperAPI testing in Phase 4
    const items = raw?.data?.products || raw?.products || [];
    if (items.length) {
      products = items.map(p => ({
        raw_name        : p.name || '',
        price_egp       : parseFloat(p.price || 0),
        original_price  : parseFloat(p.originalPrice || 0) || null,
        in_stock        : p.inStock !== false,
        stock_hint      : p.stockText || null,
        platform_item_id: String(p.id || ''),
        image_url       : p.imageUrl || null
      }));
    }

  // ── AMAZON ─────────────────────────────────────────────────────────────
  } else if (platform === 'Amazon') {
    const html = typeof raw === 'string' ? raw : JSON.stringify(raw);
    const nameMatches  = [...html.matchAll(/class="a-size-medium[^"]*"[^>]*>([^<]+)</g)];
    const priceMatches = [...html.matchAll(/class="a-price-whole"[^>]*>([\d,]+)</g)];
    products = nameMatches.slice(0, 10).map((m, i) => ({
      raw_name        : m[1].trim(),
      price_egp       : parseFloat((priceMatches[i]?.[1] || '0').replace(',', '')),
      original_price  : null,
      in_stock        : true,
      stock_hint      : null,
      platform_item_id: `amz-${i}`,
      image_url       : null
    }));

  // ── INSTASHOP (via Talabat API post-acquisition) ────────────────────────
  } else if (platform === 'InstaShop') {
    const items = raw?.data?.products || raw?.products || raw?.items || [];
    products = items.map(p => ({
      raw_name        : p.name || p.title || '',
      price_egp       : parseFloat(p.price || p.currentPrice || 0),
      original_price  : parseFloat(p.oldPrice || 0) || null,
      in_stock        : p.available !== false,
      stock_hint      : p.stockHint || null,
      platform_item_id: String(p.id || ''),
      image_url       : p.image || null
    }));

  // ── SPINNEYS ───────────────────────────────────────────────────────────
  } else if (platform === 'Spinneys') {
    const html = typeof raw === 'string' ? raw : JSON.stringify(raw);
    const items = raw?.data?.products || raw?.products || [];
    products = items.map((p, i) => ({
      raw_name        : p.name || p.title || '',
      price_egp       : parseFloat(p.price || 0),
      original_price  : parseFloat(p.comparePrice || 0) || null,
      in_stock        : p.available !== false,
      stock_hint      : null,
      platform_item_id: String(p.id || `spinneys-${i}`),
      image_url       : p.image || null
    }));

  // ── GOURMET EGYPT ──────────────────────────────────────────────────────
  } else if (platform === 'Gourmet') {
    const items = raw?.data?.products || raw?.products || [];
    products = items.map((p, i) => ({
      raw_name        : p.name || p.title || '',
      price_egp       : parseFloat(p.price || 0),
      original_price  : parseFloat(p.compare_at_price || 0) || null,
      in_stock        : p.available !== false,
      stock_hint      : p.inventory_quantity ? `${p.inventory_quantity} left` : null,
      platform_item_id: String(p.id || `gourmet-${i}`),
      image_url       : p.featured_image || null
    }));
  }

} catch (err) {
  console.error(`[${platform}] Parse error:`, err.message);
}

// Attach keyword context
return products.map(p => ({
  ...p,
  platform      : platform,
  keyword       : keyword.Keyword,
  our_sku       : keyword.Our_SKU,
  brand_expected: keyword.Brand,
  category      : keyword.Category,
  is_ours       : keyword.Is_Ours === 'TRUE' || keyword.Is_Ours === true,
  scrape_date   : new Date().toISOString().split('T')[0]
}));

